	 * @param op
	 * @return result
	 */
	private static Integer outputCalc(int a , int b , String op){

		int result = 0;
		if("+".equals(op)){
			result = a + b;
		}else if("-".equals(op)){
			result = a - b;
		}else if("*".equals(op)){
			result = a * b;
		}else if("/".equals(op)){
			result = a / b;
		}
		return result;
	}


