	public static void main(String args[]) throws Exception{
		Scanner cin= new Scanner(System.in);
	while(true){
		int n= cin.nextInt();
		int x= cin.nextInt();
		int count= 0;

		if( n==0 && x==0 ){
			break;
		}
		else{
			int i,j,k;
			for(i=1;i<n-1;i++){
			for(j=i+1;j<n;j++){
			for(k=j+1;k<n+1;k++){
				if( i+j+k==x ){
					count++;
					break;
				}
			}
			}
			}
			System.out.println(count);
		}
	}
	}
}

import java.util.*;

public class Main {

    public static void main(String[] args) {
        int n, x, count = 0;
        boolean flag = false;
        Scanner sc = new Scanner(System.in);
        while (true) {
            n = sc.nextInt();
            x = sc.nextInt();
            if (n == 0 && x == 0)
                break;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= n; j++) {
                    for (int k = 1; k <= n; k++) {
                        if (i + j + k == x)
                            flag = true;
                        if (i == j || j == k || k == i)
                            flag = false;
                        if (flag) {
                            count++;
                        }
                        flag = false;
                    }
                }
            }
            System.out.println(count / 6);
            count = 0;
        }
    }
}

public class Main {
	public static void main(String[] args){
		java.util.Scanner scan = new java.util.Scanner(System.in);
		while(true){
			int n = scan.nextInt();
			int x = scan.nextInt();
			int a,b,c = 1;
			int count = 0;

			if(n == 0 && x == 0){
				break;
			}
			for(a = 1;a<=n;a++){
				for(b = a;b<=n;b++){
					for(c = b;c<=n;c++){
						if(x == (a+b+c) && (a!=b) && (b!=c) && (c!=a)){
							count ++;
							break;
						}
					}
				}
			}
			System.out.println(count);
		}
	}
}

import java.io.BufferedReader;
