public class Main {

  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);

    int n = sc.nextInt();

    int[] b = new int[n-1];
    for (int i = 0; i < n-1; i++) {
        b[i] = sc.nextInt();
    }

    int[] a = new int[n];

