class pA {
    int res;
    char[] bucket;
    pA() {} ;
    pA(String msg)
    {
        res=0;
        bucket=new char[msg.length()];
        for(int i=0;i<msg.length();i++)
        {
            bucket[i]=msg.charAt(i);
        }
        solver();
    }
    int solver()
    {
        boolean duplicateFlag=false;
        for(int i=0;i<bucket.length;i++)
        {
            duplicateFlag=false;
            for(int j=0;j<i;j++)
            {
                if(bucket[i]==bucket[j])
                    duplicateFlag=true;
            }
            if(duplicateFlag==false)
                res+=1;
        }
        return 0;
    }
}

