		}
		for (int i = 0; i < c.length; i++) {
			c[i] = Integer.parseInt(sc.next());
		}
		int ans = 0;
		for (int i = 0; i < (1 << n); i++) {
			int sum = 0;
			for (int j = 0; j < n; j++) {
				if ((i & (1 << j)) != 0) {
