class AtCoder {

    final int A, B;

    AtCoder(FastScanner sc) {
        A = sc.nextInt();
        B = sc.nextInt();
    }

    void solve(PrintWriter out) {
        if (A == B) {
            out.println(A + B);
        } else if (A > B) {
            out.println(2 * A - 1);
        } else {
            out.println(2 * B - 1);
        }
    }

}

