    static int solve(int start, int end)
    {
        //base cases
        if(end-start<=0)
			return 0;
		if(end-start==1)
		    return Math.abs(h[end]-h[start]);


        if(dp[start]==-1)
        {
            int temp = Integer.MAX_VALUE;
            for(int i = 1; i<=k; i++)
            {   
                if(start + i<=n - 1)
