		int N = scanner.nextInt();
		int L = scanner.nextInt();
		String[] S = new String[N];
		Map<String, String> map = new TreeMap<String,String>();
		for(int i=0;i<N;i++) {
			S[i] = scanner.next();
			if(map.get(S[i])==null) {
				map.put(S[i], S[i]);
			}
			else {
				map.put(S[i]+i, S[i]);
			}
		}
